contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address member, uint amount) public {
        require(member != address(0), "member zero");

        uint lpDebtBefore = c.getmapAddress_LPDebt(address(this));
        uint supplyBefore = c.totalSupply();
        uint memberBalBefore = c.balanceOf(member);

        bool reverted;
        try c.mintSynth(member, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint lpDebtAfter = c.getmapAddress_LPDebt(address(this));
        uint supplyAfter = c.totalSupply();
        uint memberBalAfter = c.balanceOf(member);

        if (reverted) {
            assert(lpDebtAfter == lpDebtBefore && supplyAfter == supplyBefore && memberBalAfter == memberBalBefore);
        } else {
            assert(lpDebtAfter == lpDebtBefore + amount && supplyAfter == supplyBefore + amount && memberBalAfter == memberBalBefore + amount);
        }
    }
}

