contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 amount, uint256 bal) public {
        require(spender != address(0) && spender != address(this), "bad spender");
        require(amount > 0 && bal > 0, "bad inputs");

        // Give this test contract `bal` units of c using a real transfer from a holder is not possible,
        // so instead mint is not public. Use the public ERC20 surface to establish a nonzero balance:
        // burnFrom would need allowance; skip setup that may revert.
        // If the balance is insufficient, approve still succeeds regardless of balance.

        uint256 beforeBal = c.balanceOf(address(this));
        uint256 beforeSupply = c.totalSupply();

        // Approve the spender for `amount` from the test contract.
        bool approveOk = c.approve(spender, amount);

        // Transfer exactly the caller's own balance to the spender.
        bool transferOk = c.transfer(spender, beforeBal);

        bool selfTransferReverted;
        uint256 afterSelfBal;
        try c.transfer(address(this), 0) {
            selfTransferReverted = false;
            afterSelfBal = c.balanceOf(address(this));
        } catch {
            selfTransferReverted = true;
            afterSelfBal = 0;
        }

        assert(
            approveOk &&
            transferOk &&
            !selfTransferReverted &&
            c.allowance(address(this), spender) == amount &&
            afterSelfBal == 0 &&
            c.balanceOf(spender) == bal &&
            c.totalSupply() == beforeSupply
        );
    }
}

