contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address spender, uint256 initialAmount, uint256 addedValue, uint256 subtractedValue) public {
        require(spender != address(0));
        require(address(this) != address(0));

        uint256 beforeAllowance = c.allowance(address(this), spender);
        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeThisBalance = c.balanceOf(address(this));
        uint256 beforeCBaseBalance = c.balanceOf(address(c));

        c.approve(spender, initialAmount);
        c.increaseAllowance(spender, addedValue);

        uint256 afterIncrease = c.allowance(address(this), spender);

        bool decreaseOk;
        if (addedValue >= subtractedValue) {
            c.decreaseAllowance(spender, subtractedValue);
            decreaseOk = true;
        } else {
            decreaseOk = false;
            subtractedValue = 0;
        }

        uint256 afterDecrease = c.allowance(address(this), spender);
        uint256 afterTotalSupply = c.totalSupply();

        assert(afterIncrease == initialAmount + addedValue && afterDecrease == afterIncrease - subtractedValue && afterTotalSupply == beforeTotalSupply && c.balanceOf(address(this)) == beforeThisBalance && c.balanceOf(address(c)) == beforeCBaseBalance && (!decreaseOk || afterDecrease == initialAmount + addedValue - subtractedValue || beforeAllowance == type(uint256).max));
    }

    receive() external payable {}
}

