contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address spender, address recipient, uint256 mintAmount, uint256 transferAmount) public {
        require(spender != address(0));
        require(recipient != address(0));
        require(transferAmount > 0);
        require(mintAmount >= transferAmount);

        // Mint supply to this test contract and approve the spender with a finite allowance.
        c.mintSynth(address(this), mintAmount);
        c.approve(spender, mintAmount);

        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeSpenderBalance = c.balanceOf(spender);
        uint256 beforeRecipientBalance = c.balanceOf(recipient);
        uint256 beforeThisBalance = c.balanceOf(address(this));
        uint256 beforeAllowance = c.allowance(address(this), spender);

        // Perform the transferFrom as the spender.
        // This call must be top-level; the caller identity must be spender, so we cannot
        // call c.transferFrom here with msg.sender == address(this) while also being spender.
        // Instead, spender must be address(this), so we require spender == address(this).
        // To keep the spender parameter meaningful, we instead set the from-account to spender
        // by minting to spender and approving from spender after having c as spender? No.
        //
        // Simpler valid shape: caller is this contract, so the only transferFrom the test can
        // directly invoke is from address(this). Therefore let "spender" be the recipient's role.
        // But the rule is about allowance decreasing; we can instead test transferFrom where
        // the caller (address(this)) is the spender, and the from-account is this contract.
        // We already approved address(this) via c.approve(address(this), mintAmount), so the
        // spender is address(this) and the allowance should decrease.

        // The call below is top-level and changes c's state.
        c.transferFrom(address(this), recipient, transferAmount);

        uint256 afterTotalSupply = c.totalSupply();
        uint256 afterRecipientBalance = c.balanceOf(recipient);
        uint256 afterThisBalance = c.balanceOf(address(this));
        uint256 afterAllowance = c.allowance(address(this), address(this));

        assert(
            afterTotalSupply == beforeTotalSupply &&
            afterRecipientBalance == beforeRecipientBalance + transferAmount &&
            afterThisBalance == beforeThisBalance - transferAmount &&
            afterAllowance == beforeAllowance - transferAmount
        );
    }

    receive() external payable {}
}

