contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address owner, address recipient, uint256 amount, uint256 approvalAmount) public payable {
        require(owner != address(0), "owner zero");
        require(recipient != address(0), "recipient zero");
        require(approvalAmount >= amount, "insufficient approval");

        // Mint tokens to owner: mintSynth is only callable by a curated pool, but in this standalone
        // test we only use it to establish a positive balance for the transferFrom check if possible.
        // If the call reverts (not a curated pool), we skip the stateful assertion below.
        bool minted;
        try c.mintSynth(owner, approvalAmount + amount) {
            minted = true;
        } catch {
            minted = false;
        }

        uint256 beforeOwnerBal = c.balanceOf(owner);
        uint256 beforeRecipientBal = c.balanceOf(recipient);

        bool approved;
        try c.approve(recipient, approvalAmount) {
            approved = true;
        } catch {
            approved = false;
        }

        bool transferred;
        try c.transferFrom(owner, recipient, amount) {
            transferred = true;
        } catch {
            transferred = false;
        }

        uint256 afterOwnerBal = c.balanceOf(owner);
        uint256 afterRecipientBal = c.balanceOf(recipient);
        uint256 afterAllowance = c.allowance(owner, recipient);

        assert(
            (!minted && !transferred) ||
            (minted && approved && transferred && afterOwnerBal + amount == beforeOwnerBal && afterRecipientBal == beforeRecipientBal + amount && afterAllowance == approvalAmount - amount)
        );
    }

    receive() external payable {}
}

