contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address member,
        uint256 synthAmount,
        address pool,
        uint256 extraLp,
        uint256 extraDebt
    ) public {
        require(member != address(0), "bad member");
        require(synthAmount != 0, "zero synth");
        require(pool != address(0), "bad pool");

        uint256 beforePoolLP = iBEP20(pool).balanceOf(address(c));

        // Mint synthetic tokens to the test contract, which credits c's internal
        // accounting for the pool as long as the pool has enough LP collateral.
        c.mintSynth(address(this), synthAmount);

        uint256 lpBalance = c.getmapAddress_LPBalance(pool);
        uint256 lpDebt = c.getmapAddress_LPDebt(pool);
        if (lpDebt == 0) {
            // Not enough collateral was seen to create a debt; nothing to burn.
            assert(c.totalSupply() >= synthAmount);
            return;
        }

        uint256 expectedUnits = (synthAmount * lpBalance) / lpDebt;

        // Create the synthetic tokens inside c so that burnSynth can burn them.
        c.transfer(address(c), synthAmount);

        uint256 beforeCallerLP = iBEP20(pool).balanceOf(address(this));

        // This burn is the deciding call and will update c's state.
        c.burnSynth();

        uint256 afterPoolLP = iBEP20(pool).balanceOf(address(c));
        uint256 afterCallerLP = iBEP20(pool).balanceOf(address(this));
        uint256 currentLpBalance = c.getmapAddress_LPBalance(pool);

        // If the pool actually holds LP tokens for c, the burn can move them,
        // and the amount is fixed by the synthetic amount, LP balance, and debt
        // observed before the deciding call.
        if (beforeCallerLP > afterCallerLP) {
            assert(beforeCallerLP - afterCallerLP == expectedUnits);
            assert(afterPoolLP == beforePoolLP);
        }

        assert(
            currentLpBalance + (beforeCallerLP - afterCallerLP) == lpBalance ||
            beforeCallerLP <= afterCallerLP
        );
    }
}

