contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address member, uint amount) public {
        require(member != address(0), "!member");
        require(amount > 0, "!amount");

        // Read-only precondition: c's deployment must have registered a DAO.
        // and this test contract must be a curated pool in that DAO's pool factory.
        require(address(c).code.length > 0, "!code");
        address base = c.BASE();
        require(base != address(0), "!base");
        (bool okRead,, bytes memory retRead) = base.staticcall(
            abi.encodeWithSignature("DAO()")
        );
        require(okRead && retRead.length >= 32, "!dao");
        address dao = abi.decode(retRead, (address));
        require(dao != address(0), "!dao0");
        (bool okFac,, bytes memory retFac) = dao.staticcall(
            abi.encodeWithSignature("POOLFACTORY()")
        );
        require(okFac && retFac.length >= 32, "!factory");
        address factory = abi.decode(retFac, (address));
        (bool okCur,, bytes memory retCur) = factory.staticcall(
            abi.encodeWithSignature("isCuratedPool(address)", address(this))
        );
        require(okCur && retCur.length >= 32, "!cur");
        require(abi.decode(retCur, (bool)), "!curated");

        uint256 supplyBefore = c.totalSupply();
        uint256 memberBalBefore = c.balanceOf(member);
        uint256 contractBalBefore = c.balanceOf(address(this));

        // The deciding call: since address(this) is a curated pool, this must not revert.
        uint256 returnedAmount = c.mintSynth(member, amount);

        uint256 supplyAfter = c.totalSupply();
        uint256 memberBalAfter = c.balanceOf(member);
        uint256 contractBalAfter = c.balanceOf(address(this));

        // General rule: mintSynth mints exactly `amount` to `member`, and the pool's
        // LP-balance accounting records the same amount as newly added synthetic debt.
        assert(returnedAmount == amount
            && supplyAfter == supplyBefore + amount
            && memberBalAfter == memberBalBefore + amount
            && c.getmapAddress_LPDebt(address(this)) == amount
            && c.getmapAddress_LPBalance(address(this)) >= contractBalBefore
            && c.balanceOf(member) > memberBalBefore);
    }

    receive() external payable {}
}

