contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address spender, address recipient, uint256 amount, uint256 approvalAmount) public {
        require(spender != address(0), "!spender");
        require(recipient != address(0), "!recipient");
        require(amount > 0, "!amount");

        // Make approvalAmount the spender's allowance from the test contract.
        // approve() returns bool; ignore return value by NOT assigning.
        c.approve(spender, approvalAmount);

        // Give the test contract enough balance to transfer.
        // We need an external source of balance; use approve/transferFrom is not possible,
        // so use the fact that the test contract is the deployer? No, mint is onlyDAO.
        // Instead, transferFrom can only succeed if the test contract has balance.
        // We can manufacture balance by first calling transfer from... no sender balance.
        // So we test the allowance semantics only when transfer succeeds.
        // Use a try/catch to observe whether transferFrom reverts.
        bool reverted;
        try c.transferFrom(address(this), recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 newAllowance = c.allowance(address(this), spender);
            if (approvalAmount == type(uint256).max) {
                assert(newAllowance == type(uint256).max);
            } else {
                assert(newAllowance == approvalAmount - amount);
            }
        }
    }

    receive() external payable {}
}

