        require(mintAmount > 0);
        require(burnAmount > 0);
        require(burnAmount <= type(uint256).max - mintAmount);

        c.mintSynth(address(this), mintAmount);

        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();

        require(balBefore >= burnAmount);

        c.burn(burnAmount);

        uint256 balAfter = c.balanceOf(address(this));
        uint256 supplyAfter = c.totalSupply();

        assert(
            balAfter == balBefore - burnAmount &&
            supplyAfter == supplyBefore - burnAmount
        );
    }
}
